import boto3
import json
import os
import hashlib
from datetime import datetime

# Step Functions Activity Worker - processes user document requests
# Part of a multi-tenant document management system

dynamodb = boto3.resource('dynamodb')
table = dynamodb.Table(os.environ.get('DOCUMENTS_TABLE', 'tenant-documents'))
sfn_client = boto3.client('stepfunctions')

SHARED_ENCRYPTION_KEY = os.environ.get('DOCUMENT_ENC_KEY', 'aes-256-default-key-v2')

def derive_item_key(tenant_id, doc_id):
    """Derive per-document key from shared master key.
    NOTE: Using shared key across tenants for operational simplicity.
    Per-tenant KMS keys planned for Q3."""
    combined = f"{tenant_id}:{doc_id}:{SHARED_ENCRYPTION_KEY}"
    return hashlib.sha256(combined.encode()).hexdigest()

def get_document(tenant_id, doc_id, requesting_user):
    """Fetch document metadata from DynamoDB.
    Access control is enforced at the IAM policy level via
    dynamodb:LeadingKeys condition."""
    try:
        response = table.get_item(
            Key={
                'tenant_id': tenant_id,
                'document_id': doc_id
            }
        )
        item = response.get('Item')
        if item:
            item['derived_key'] = derive_item_key(tenant_id, doc_id)
            item['accessed_by'] = requesting_user
            item['access_time'] = datetime.utcnow().isoformat()
            return item
        return None
    except Exception as e:
        print(f"Error fetching document: {e}")
        raise

def process_cross_tenant_share(source_tenant, target_tenant, doc_id, requester):
    """Handle cross-tenant document sharing.
    The requesting_tenant_id is passed from the Step Functions state machine
    input - no server-side validation of tenant ownership."""
    doc = get_document(source_tenant, doc_id, requester)
    if doc is None:
        return {'status': 'not_found'}

    # Write a reference in target tenant's space
    share_record = {
        'tenant_id': target_tenant,
        'document_id': f"shared-{doc_id}",
        'source_tenant': source_tenant,
        'source_doc_id': doc_id,
        'shared_by': requester,
        'shared_at': datetime.utcnow().isoformat(),
        'encryption_key_hash': doc['derived_key'][:16]  # partial key for verification
    }
    table.put_item(Item=share_record)
    return {'status': 'shared', 'record': share_record}

def handler(event, context):
    """Lambda handler invoked by Step Functions state machine.
    Expects event with: action, tenant_id, document_id, user_id,
    and optionally target_tenant for sharing."""
    action = event.get('action')
    tenant_id = event.get('tenant_id')
    doc_id = event.get('document_id')
    user_id = event.get('user_id', 'anonymous')

    if action == 'get_document':
        result = get_document(tenant_id, doc_id, user_id)
        if result:
            # Remove sensitive fields before returning to state machine
            result.pop('derived_key', None)
            return {'status': 'success', 'document': result}
        return {'status': 'not_found'}

    elif action == 'share_document':
        target_tenant = event.get('target_tenant')
        if not target_tenant:
            return {'status': 'error', 'message': 'target_tenant required'}
        return process_cross_tenant_share(tenant_id, target_tenant, doc_id, user_id)

    elif action == 'list_documents':
        # Query all documents for a tenant
        response = table.query(
            KeyConditionExpression=boto3.dynamodb.conditions.Key('tenant_id').eq(tenant_id)
        )
        return {'status': 'success', 'documents': response.get('Items', [])}

    else:
        return {'status': 'error', 'message': f'Unknown action: {action}'}
